insert into passages (id, text, difficulty_level, b, active) values
('1a4334e6-a7c5-4bd5-a858-e7db28f6e2be', 'The concept of "planned obsolescence" refers to the deliberate design of products with an artificially limited useful life, compelling consumers to replace them more frequently than would otherwise be necessary. Although the term is sometimes invoked as a conspiracy theory, historians of technology point to well-documented instances of the practice, most notably the Phoebus cartel of the 1920s and 1930s, in which major lightbulb manufacturers colluded to limit the lifespan of incandescent bulbs to roughly a thousand hours, despite possessing the technical capacity to produce bulbs that lasted far longer. Proponents of a more charitable interpretation argue that what critics label planned obsolescence is often simply the natural consequence of rapid technological progress: a smartphone released five years ago may not be intentionally sabotaged, but its diminished utility relative to newer models reflects genuine advances in processing power and software design rather than deliberate sabotage. Nevertheless, a number of manufacturers have faced legal action and regulatory scrutiny over practices such as software updates that noticeably slow down older devices, batteries that are difficult or prohibitively expensive to replace, and components that are deliberately soldered or glued in ways that discourage repair. In response to mounting public pressure, some jurisdictions have begun enacting "right to repair" legislation, requiring manufacturers to make spare parts, tools, and repair documentation available to consumers and independent repair shops, a shift that industry groups have resisted on the grounds that it could compromise product safety and intellectual property protections, though critics counter that such objections often mask a reluctance to forgo the profits generated by frequent replacement purchases.', 5, 2.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('0316f2d5-9d36-4c5e-8aa1-4109449e2fe7', 'sentence_completion', 'The diplomat''s carefully ___ statement managed to avoid controversy while still signaling the government''s true position.', NULL, '[{"id": "a", "text": "equivocal"}, {"id": "d", "text": "reckless"}, {"id": "c", "text": "candid"}, {"id": "b", "text": "transparent"}]'::jsonb, 0, '{"strategy": "avoid controversy while still signaling position = נמנע ממחלוקת אך עדיין מאותת עמדה. איזו הצהרה עושה את שניהם?", "correct_reason": "equivocal = דו-משמעי. הצהרה דו-משמעית מאפשרת רמז מבלי להתחייב.", "options_analysis": ["נכון! equivocal = דו-משמעי — מתאים להימנעות ממחלוקת תוך אותות עמדה", "reckless = פזיז — לא מתאים לדיפלומטיה זהירה", "candid = כן וישיר — הפוך מהימנעות ממחלוקת", "transparent = שקוף — הפוך מהצהרה שנמנעת ממחלוקת"]}', 1.77, 2.0, 0.25, 5, 'ai', NULL, true),
('e12878c7-8b8b-4d1b-9384-187e063fc747', 'sentence_completion', 'The critic''s review was so ___ that the author''s reputation never fully recovered.', NULL, '[{"id": "a", "text": "tepid"}, {"id": "d", "text": "scathing"}, {"id": "b", "text": "mild"}, {"id": "c", "text": "laudatory"}]'::jsonb, 1, '{"strategy": "reputation never fully recovered = מוניטין לא התאושש. איזו ביקורת פוגעת כך קשות?", "correct_reason": "scathing = צורבת/קטלנית. ביקורת קטלנית פוגעת קשות במוניטין.", "options_analysis": ["tepid = פושרת — לא חזקה מספיק לפגיעה כה קשה", "נכון! scathing = קטלנית — מתאימה לפגיעה חמורה במוניטין", "mild = מתונה — לא חזקה מספיק לפגיעה כה קשה", "laudatory = משבחת — הפוך מפגיעה במוניטין"]}', 1.62, 2.0, 0.25, 5, 'ai', NULL, true),
('131d1ad4-c3f1-46ed-bbe9-09c2325279e2', 'sentence_completion', 'The board''s ___ handling of the layoffs drew sharp criticism from employees and the press alike.', NULL, '[{"id": "d", "text": "gentle"}, {"id": "b", "text": "compassionate"}, {"id": "a", "text": "callous"}, {"id": "c", "text": "careful"}]'::jsonb, 2, '{"strategy": "drew sharp criticism = משכה ביקורת חריפה. איזה טיפול בפיטורים מושך ביקורת חריפה?", "correct_reason": "callous = אטום/חסר רגישות. טיפול אטום בפיטורים מושך ביקורת חריפה.", "options_analysis": ["gentle = עדין — הפוך מביקורת חריפה", "compassionate = חומל — הפוך מביקורת חריפה", "נכון! callous = אטום — מתאים לביקורת חריפה מעובדים ותקשורת", "careful = זהיר — הפוך מטיפול שמושך ביקורת"]}', 1.63, 2.0, 0.25, 5, 'ai', NULL, true),
('5c251054-f701-4c31-9998-865b3dd6c5fc', 'sentence_completion', 'The scholar''s argument, though initially ___, gradually gained acceptance as more evidence emerged.', NULL, '[{"id": "b", "text": "popular"}, {"id": "d", "text": "mainstream"}, {"id": "c", "text": "conventional"}, {"id": "a", "text": "heterodox"}]'::jsonb, 3, '{"strategy": "gradually gained acceptance = בהדרגה זכה להכרה. איזה טיעון זקוק לזמן כדי לזכות בהכרה?", "correct_reason": "heterodox = לא-שגרתי/חריג. טיעון חריג לוקח זמן לזכות בהכרה.", "options_analysis": ["popular = פופולרי — סותר את הצורך בהכרה הדרגתית", "mainstream = מקובל — סותר את הצורך ב''gradually gained acceptance''", "conventional = שגרתי — סותר את הצורך בהכרה הדרגתית", "נכון! heterodox = חריג — מתאים לטיעון שזקוק לזמן לזכות בהכרה"]}', 2.05, 2.0, 0.25, 5, 'ai', NULL, true),
('1f0298ad-bc95-489a-a1aa-3a4e08d649e6', 'sentence_completion', 'The negotiations reached an ___ , with both sides unable to bridge their fundamental differences.', NULL, '[{"id": "d", "text": "impasse"}, {"id": "a", "text": "resolution"}, {"id": "b", "text": "agreement"}, {"id": "c", "text": "accord"}]'::jsonb, 0, '{"strategy": "unable to bridge their fundamental differences = לא הצליחו לגשר על הבדלים יסודיים. לאן מגיעים משא ומתן כשלא מגשרים?", "correct_reason": "impasse = מבוי סתום. חוסר יכולת לגשר מוביל למבוי סתום.", "options_analysis": ["נכון! impasse = מבוי סתום — מתאים לחוסר יכולת לגשר על הבדלים", "resolution = פתרון — הפוך מ''unable to bridge''", "agreement = הסכם — הפוך מ''unable to bridge''", "accord = הסכמה — הפוך מ''unable to bridge''"]}', 2.05, 2.0, 0.25, 5, 'ai', NULL, true),
('016a35e0-7aa8-4256-a0a3-4ae451348647', 'sentence_completion', 'The politician''s ___ remarks, intended to appease both sides, ultimately satisfied neither.', NULL, '[{"id": "a", "text": "direct"}, {"id": "b", "text": "ambiguous"}, {"id": "c", "text": "clear"}, {"id": "d", "text": "decisive"}]'::jsonb, 1, '{"strategy": "intended to appease both sides...satisfied neither = נועד לרצות את שני הצדדים...לא סיפק אף אחד. איזו הערה נכשלת כך?", "correct_reason": "ambiguous = דו-משמעית. הערה דו-משמעית שמנסה לרצות את כולם לרוב לא מספקת אף צד.", "options_analysis": ["direct = ישירה — הפוך מניסיון לרצות את שני הצדדים", "נכון! ambiguous = דו-משמעית — מתאימה לניסיון כושל לרצות את כולם", "clear = ברורה — הפוך מניסיון לרצות את שני הצדדים במעורפל", "decisive = החלטית — הפוך מניסיון לרצות את שני הצדדים"]}', 1.65, 2.0, 0.25, 5, 'ai', NULL, true),
('4bd3ad73-8c45-425f-bebb-d04e7b99c78b', 'sentence_completion', 'The company''s ___ growth over the past decade has made it a case study in business schools worldwide.', NULL, '[{"id": "a", "text": "gradual"}, {"id": "b", "text": "stagnant"}, {"id": "d", "text": "meteoric"}, {"id": "c", "text": "modest"}]'::jsonb, 2, '{"strategy": "case study in business schools worldwide = מקרה לימוד בבתי ספר למנהל עסקים ברחבי העולם. איזו צמיחה זוכה לתשומת לב כזו?", "correct_reason": "meteoric = מטאורית/מהירה מאוד. צמיחה מטאורית זוכה להיות מקרה מחקר.", "options_analysis": ["gradual = הדרגתית — פחות דרמטית מכדי לזכות בתשומת לב עולמית כזו", "stagnant = קפוא — הפוך מצמיחה שזוכה למחקר כה נרחב", "נכון! meteoric = מטאורית — מתאימה לצמיחה יוצאת דופן שראויה למחקר", "modest = צנועה — הפוך מצמיחה יוצאת דופן"]}', 2.25, 2.0, 0.25, 5, 'ai', NULL, true),
('0a424bfa-bae0-49b0-99a0-c32d06e45bca', 'sentence_completion', 'Despite the CEO''s ___ assurances, investors remained deeply skeptical about the company''s future.', NULL, '[{"id": "b", "text": "doubtful"}, {"id": "d", "text": "weak"}, {"id": "c", "text": "hesitant"}, {"id": "a", "text": "emphatic"}]'::jsonb, 3, '{"strategy": "despite...assurances, investors remained skeptical = למרות הבטחות, משקיעים נשארו ספקנים. איזו הבטחה נכשלת בלשכנע למרות עוצמתה?", "correct_reason": "emphatic = נחרצת/תקיפה. גם הבטחה תקיפה לא הצליחה לשכנע.", "options_analysis": ["doubtful = מפוקפקת — לא הגיוני שמנהל יתן הבטחה מפוקפקת", "weak = חלשה — פחות מתאים ל''despite'' שמרמז על ניסיון משכנע", "hesitant = מהוססת — פחות מתאים ל''despite'' שמרמז על ניסיון תקיף", "נכון! emphatic = נחרצת — מתאימה ל''despite'' שמרמז שההבטחה הייתה חזקה אך לא הספיקה"]}', 1.63, 2.0, 0.25, 5, 'ai', NULL, true),
('2afe59f1-3128-41fa-bd20-5939e85b693e', 'sentence_completion', 'The artist''s early work was largely ___ by critics, who only recognized its brilliance decades later.', NULL, '[{"id": "b", "text": "dismissed"}, {"id": "a", "text": "praised"}, {"id": "d", "text": "celebrated"}, {"id": "c", "text": "honored"}]'::jsonb, 0, '{"strategy": "only recognized its brilliance decades later = הוכר הבריק שלה רק עשרות שנים אחר כך. מה קרה ליצירה המוקדמת בהתחלה?", "correct_reason": "dismissed = נדחתה. יצירה שהוכרה רק מאוחר יותר נדחתה בהתחלה.", "options_analysis": ["נכון! dismissed = נדחתה — מתאים להכרה מאוחרת בלבד", "praised = שובחה — סותר ''only recognized...decades later''", "celebrated = חוגגה — סותר ''only recognized...decades later''", "honored = כובדה — סותר ''only recognized...decades later''"]}', 2.15, 2.0, 0.25, 5, 'ai', NULL, true),
('5562f9a3-2e53-49ce-b5e2-6d5ffafea379', 'sentence_completion', 'The report''s ___ conclusions were later contradicted by more rigorous studies.', NULL, '[{"id": "c", "text": "modest"}, {"id": "d", "text": "hasty"}, {"id": "b", "text": "careful"}, {"id": "a", "text": "cautious"}]'::jsonb, 1, '{"strategy": "later contradicted by more rigorous studies = נסתרו מאוחר יותר על ידי מחקרים קפדניים יותר. אילו מסקנות נסתרות בקלות?", "correct_reason": "hasty = פזיזות/נחפזות. מסקנות פזיזות נוטות להיסתר על ידי מחקר קפדני יותר.", "options_analysis": ["modest = צנועות — לא מתאר את מהירות/פזיזות המסקנה", "נכון! hasty = פזיזות — מתאימות למסקנות שנסתרו במחקר קפדני יותר", "careful = קפדניות — פחות סביר שייסתרו כה בקלות", "cautious = זהירות — פחות סביר שייסתרו כה בקלות"]}', 2.18, 2.0, 0.25, 5, 'ai', NULL, true),
('ea088ba0-4cb6-402a-9f16-484279aa858f', 'sentence_completion', 'The firm''s ___ business practices eventually led to a lengthy investigation by regulators.', NULL, '[{"id": "c", "text": "transparent"}, {"id": "b", "text": "exemplary"}, {"id": "a", "text": "dubious"}, {"id": "d", "text": "ethical"}]'::jsonb, 2, '{"strategy": "led to a lengthy investigation by regulators = הובילו לחקירה ארוכה. אילו פרקטיקות עסקיות מובילות לחקירה?", "correct_reason": "dubious = מפוקפקות. פרקטיקות מפוקפקות מובילות לחקירה רגולטורית.", "options_analysis": ["transparent = שקופות — הפוך מגרימה לחקירה", "exemplary = למופת — הפוך מגרימה לחקירה", "נכון! dubious = מפוקפקות — מתאימות לגרימת חקירה רגולטורית", "ethical = אתיות — הפוך מגרימה לחקירה"]}', 2.17, 2.0, 0.25, 5, 'ai', NULL, true),
('c69a5251-2564-4869-b55f-36e6ac69b05a', 'sentence_completion', 'The professor''s willingness to ___ his own earlier theories, in light of new evidence, earned him respect among peers.', NULL, '[{"id": "d", "text": "defend"}, {"id": "a", "text": "promote"}, {"id": "c", "text": "reinforce"}, {"id": "b", "text": "repudiate"}]'::jsonb, 3, '{"strategy": "in light of new evidence...earned respect = לאור ראיות חדשות...זכה לכבוד. מה עושה חוקר מכובד עם תיאוריה ישנה שראיות חדשות סותרות?", "correct_reason": "repudiate = להתכחש ל-/לדחות. נכונות לדחות תיאוריה ישנה לאור ראיות חדשות מעידה על יושרה מדעית.", "options_analysis": ["defend = להגן על — פחות מתאים ל''in light of new evidence'' שסותרת את התיאוריה הישנה", "promote = לקדם — סותר את ההיגיון של ראיות חדשות סותרות", "reinforce = לחזק — סותר את ההיגיון של ראיות חדשות סותרות", "נכון! repudiate = לדחות — מתאים ליושרה מדעית שזוכה לכבוד"]}', 2.12, 2.0, 0.25, 5, 'ai', NULL, true),
('99b0ad1b-d21d-47b9-8b7f-65e7d19acd45', 'restatement', 'The findings, while not conclusive, nonetheless lend considerable weight to the hypothesis that had long been dismissed as implausible.', NULL, '[{"id": "d", "text": "Although not fully conclusive, the findings provide substantial support for a hypothesis previously considered unlikely."}, {"id": "c", "text": "The hypothesis was proven true long before these findings were discovered."}, {"id": "a", "text": "The findings definitively prove a hypothesis that everyone had always accepted as obvious."}, {"id": "b", "text": "The findings completely disprove a hypothesis that had never been seriously considered."}]'::jsonb, 0, '{"strategy": "while not conclusive, lend considerable weight = לא סופי אך תומך משמעותית. ניגוד עדין.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: לא חד-משמעי אך תומך משמעותית בהשערה שנחשבה לא סבירה", "סותר את הרצף הכרונולוגי — הממצאים הם החדשים שתומכים בהשערה", "הפוך — ''definitively prove'' סותר ''not conclusive'', וגם ''accepted as obvious'' סותר ''dismissed as implausible''", "הפוך גמור — ''disprove'' סותר ''lend considerable weight''"]}', 2.06, 2.0, 0.25, 5, 'ai', NULL, true),
('593c3827-cbd8-4043-a487-2e0194d4d83e', 'restatement', 'The committee''s recommendation, though nonbinding, carries considerable political weight given the stature of its members.', NULL, '[{"id": "d", "text": "The committee''s recommendation has no influence whatsoever."}, {"id": "c", "text": "Although not legally required to be followed, the recommendation is politically significant due to the members'' prominence."}, {"id": "a", "text": "The committee''s recommendation is legally binding on all parties."}, {"id": "b", "text": "The members of the committee have no political stature at all."}]'::jsonb, 1, '{"strategy": "though nonbinding, carries considerable weight = למרות שלא מחייב, בעל משקל רב. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — ''no influence'' סותר ''considerable political weight''", "נכון! אותה משמעות מדויקת: לא מחייב חוקית אך משמעותי פוליטית בשל מעמד החברים", "הפוך — ''legally binding'' סותר ''nonbinding''", "הפוך — סותר ''given the stature of its members''"]}', 2.06, 2.0, 0.25, 5, 'ai', NULL, true),
('030d2d1e-81b9-4e2b-a84c-1146207acf9e', 'restatement', 'The novel''s ostensibly simple plot belies a deeply complex exploration of memory and identity.', NULL, '[{"id": "a", "text": "The novel has an overtly complicated plot with no simple elements."}, {"id": "d", "text": "The novel''s plot is exactly as simple as it appears, with no deeper themes."}, {"id": "b", "text": "Beneath its seemingly straightforward plot, the novel actually explores memory and identity in great depth."}, {"id": "c", "text": "The novel does not address memory or identity in any way."}]'::jsonb, 2, '{"strategy": "ostensibly simple...belies deeply complex = לכאורה פשוט...מסתיר מורכבות. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — ''overtly complicated plot'' סותר ''ostensibly simple plot''", "הפוך — סותר ''belies a deeply complex exploration''", "נכון! אותה משמעות מדויקת: לכאורה פשוט אך בפועל מורכב בעומק בנושאי זיכרון וזהות", "הפוך גמור — סותר ''exploration of memory and identity''"]}', 2.18, 2.0, 0.25, 5, 'ai', NULL, true),
('846c7ddf-e37d-49a8-844b-3915e50b6295', 'restatement', 'The startup''s meteoric rise, while impressive, masked underlying financial vulnerabilities that would later prove catastrophic.', NULL, '[{"id": "c", "text": "The startup''s financial vulnerabilities were obvious to everyone from the start."}, {"id": "b", "text": "The startup''s slow growth revealed no financial problems at all."}, {"id": "d", "text": "The startup''s rise had no connection to any financial issues."}, {"id": "a", "text": "Although the startup''s rapid growth was impressive, it concealed financial weaknesses that eventually caused disaster."}]'::jsonb, 3, '{"strategy": "while impressive, masked vulnerabilities = מרשים אך הסתיר חולשות. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — ''masked'' = הוסתרו, לא היו גלויות לכולם", "הפוך — ''slow growth'' סותר ''meteoric rise'', ''no financial problems'' סותר ''catastrophic''", "סותר ''would later prove catastrophic'' — יש קשר ישיר", "נכון! אותה משמעות מדויקת: צמיחה מהירה ומרשימה הסתירה חולשות שהובילו לאסון"]}', 2.01, 2.0, 0.25, 5, 'ai', NULL, true),
('3445877f-4b1a-4245-af6d-9602c913ceeb', 'restatement', 'The senator''s stance, though publicly unwavering, was reportedly the subject of considerable private doubt.', NULL, '[{"id": "b", "text": "Although the senator appeared publicly firm in his position, he reportedly harbored significant doubts privately."}, {"id": "c", "text": "The senator''s stance was weak both publicly and privately."}, {"id": "a", "text": "The senator had no private doubts about his public stance."}, {"id": "d", "text": "The senator publicly expressed doubt about his own position."}]'::jsonb, 0, '{"strategy": "though publicly unwavering, private doubt = פומבי איתן אך ספק פרטי. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: פומבית איתן, אך פרטית מלא ספקות מדווחים", "הפוך — סותר ''unwavering'' (הפומבי היה איתן, לא חלש)", "הפוך — סותר ''considerable private doubt''", "הפוך — ''publicly expressed doubt'' סותר ''publicly unwavering''"]}', 1.88, 2.0, 0.25, 5, 'ai', NULL, true),
('f485af5a-bc74-4d1a-b5ce-0e4237887802', 'restatement', 'The evidence, though circumstantial, was corroborated by enough independent sources to be deemed credible.', NULL, '[{"id": "d", "text": "The evidence was dismissed because no independent sources supported it."}, {"id": "a", "text": "Even though the evidence was indirect, it was confirmed by multiple independent sources and considered believable."}, {"id": "c", "text": "No sources ever confirmed the circumstantial evidence."}, {"id": "b", "text": "The evidence was direct and required no corroboration from other sources."}]'::jsonb, 1, '{"strategy": "though circumstantial, corroborated by enough sources = נסיבתי אך אומת ע''י מספיק מקורות. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''corroborated by enough independent sources''", "נכון! אותה משמעות מדויקת: עקיף אך אומת על ידי מקורות עצמאיים ונחשב אמין", "הפוך — סותר ''corroborated''", "הפוך — ''direct'' סותר ''circumstantial'', וגם סותר את הצורך באימות"]}', 1.64, 2.0, 0.25, 5, 'ai', NULL, true),
('4015c16d-fab2-4e51-9e2c-437da437f496', 'restatement', 'The reform, hailed by supporters as revolutionary, was dismissed by critics as merely cosmetic.', NULL, '[{"id": "b", "text": "Critics praised the reform as revolutionary while supporters called it cosmetic."}, {"id": "d", "text": "No one had any opinion about the reform."}, {"id": "a", "text": "Supporters praised the reform as groundbreaking, while critics viewed it as superficial and insignificant."}, {"id": "c", "text": "Both supporters and critics agreed the reform was revolutionary."}]'::jsonb, 2, '{"strategy": "hailed as revolutionary...dismissed as cosmetic = ניגוד בין תפיסות.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — התפקידים הפוכים מהמקור", "סותר את קיום הדעות המנוגדות", "נכון! אותה משמעות מדויקת: תומכים ראו כפורץ דרך, מבקרים ראו כשטחי", "סותר את הניגוד המפורש בין תומכים למבקרים"]}', 1.92, 2.0, 0.25, 5, 'ai', NULL, true),
('44ed6aa0-56a4-48d5-bcc8-dd6cdb63401a', 'restatement', 'The memoir''s unflinching honesty about the author''s failures, rather than diminishing her legacy, ultimately enhanced it.', NULL, '[{"id": "b", "text": "The author''s legacy remained completely unaffected by the memoir."}, {"id": "d", "text": "The memoir''s honesty about failures damaged the author''s legacy irreparably."}, {"id": "c", "text": "The memoir avoided any discussion of the author''s failures."}, {"id": "a", "text": "Instead of harming her reputation, the author''s candid admission of failures actually strengthened her legacy."}]'::jsonb, 3, '{"strategy": "rather than diminishing, enhanced = במקום להחליש, חיזק. ניגוד ציפייה-תוצאה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר ''ultimately enhanced it'' — כן הייתה השפעה", "הפוך — ''damaged...irreparably'' סותר ''enhanced it''", "הפוך — סותר ''unflinching honesty about the author''s failures''", "נכון! אותה משמעות מדויקת: כנות לגבי כישלונות לא פגעה אלא חיזקה את המורשת"]}', 1.78, 2.0, 0.25, 5, 'ai', NULL, true),
('b31f9ef1-c5a4-4d61-ac84-61da8fe44166', 'restatement', 'The merger, long anticipated by analysts, still managed to catch the market by surprise in its timing.', NULL, '[{"id": "c", "text": "Even though analysts had long expected the merger, its timing still surprised the market."}, {"id": "d", "text": "The merger''s timing was announced years in advance with no surprise."}, {"id": "a", "text": "The market fully expected the exact timing of the merger."}, {"id": "b", "text": "No analysts ever anticipated the merger would happen."}]'::jsonb, 0, '{"strategy": "long anticipated, still surprised in timing = ציפייה כללית אך הפתעה בתזמון.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: אנליסטים ציפו למיזוג, אך התזמון עדיין הפתיע את השוק", "הפוך — סותר ''catch the market by surprise''", "הפוך — סותר ''catch the market by surprise in its timing''", "הפוך — סותר ''long anticipated by analysts''"]}', 1.9, 2.0, 0.25, 5, 'ai', NULL, true),
('2669cb71-ffcd-4bf0-a7af-31f10f21f3d5', 'restatement', 'The professor''s terse feedback, though initially discouraging to students, was ultimately intended to sharpen their critical thinking.', NULL, '[{"id": "d", "text": "The professor''s feedback had no purpose or intention behind it."}, {"id": "c", "text": "Although the professor''s brief feedback initially discouraged students, it was meant to strengthen their critical thinking skills."}, {"id": "b", "text": "The professor''s feedback was verbose and consistently encouraging."}, {"id": "a", "text": "The professor never provided any feedback to students."}]'::jsonb, 1, '{"strategy": "though initially discouraging, intended to sharpen thinking = ניגוד בין תחושה ראשונית למטרה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר ''ultimately intended to sharpen their critical thinking''", "נכון! אותה משמעות מדויקת: משוב קצר שהרתיע בהתחלה, אך נועד לחדד חשיבה ביקורתית", "הפוך — ''verbose'' סותר ''terse'', ''encouraging'' סותר ''discouraging''", "הפוך — סותר את קיום המשוב עצמו"]}', 2.12, 2.0, 0.25, 5, 'ai', NULL, true),
('161e780a-9b17-4555-b39f-a28a515ab9d2', 'restatement', 'The city''s decision to overhaul its transit system, though costly in the short term, is projected to yield substantial economic benefits over the coming decades.', NULL, '[{"id": "a", "text": "The transit overhaul is expected to be free and yield no economic benefits."}, {"id": "d", "text": "The transit overhaul will only benefit the city in the very short term."}, {"id": "c", "text": "Despite being expensive initially, the transit system overhaul is expected to generate significant economic gains in the long run."}, {"id": "b", "text": "The city decided against overhauling its transit system entirely."}]'::jsonb, 2, '{"strategy": "though costly short-term, projected substantial benefits long-term = ניגוד זמן קצר-ארוך.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''costly in the short term'' ו''substantial economic benefits''", "הפוך — סותר ''over the coming decades'' שמרמז על טווח ארוך", "נכון! אותה משמעות מדויקת: יקר בטווח קצר, אך צפוי לתועלת כלכלית משמעותית בטווח ארוך", "הפוך — סותר את קיום ההחלטה לשפץ"]}', 2.22, 2.0, 0.25, 5, 'ai', NULL, true),
('675141c7-1d3d-460c-9cab-db165e12c832', 'restatement', 'The witness''s testimony, initially dismissed as unreliable, later proved pivotal in securing the conviction.', NULL, '[{"id": "d", "text": "The witness never testified in the case at all."}, {"id": "b", "text": "The witness''s testimony was always considered crucial and was never doubted."}, {"id": "c", "text": "The testimony had no impact on the outcome of the case."}, {"id": "a", "text": "Though first regarded as untrustworthy, the testimony ultimately became essential to obtaining the conviction."}]'::jsonb, 3, '{"strategy": "initially dismissed, later proved pivotal = ניגוד בין תחילה לסוף.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר את קיום העדות עצמה", "הפוך — סותר ''initially dismissed as unreliable''", "הפוך — סותר ''proved pivotal in securing the conviction''", "נכון! אותה משמעות מדויקת: תחילה נחשבה לא אמינה, אך הפכה מכרעת להרשעה"]}', 1.98, 2.0, 0.25, 5, 'ai', NULL, true),
('3e0e7786-1b87-4e52-a76c-ebf06dfbab79', 'reading_comprehension', 'What is the primary purpose of the passage?', '1a4334e6-a7c5-4bd5-a858-e7db28f6e2be', '[{"id": "a", "text": "To examine the concept of planned obsolescence and the debate surrounding its causes and remedies"}, {"id": "b", "text": "To provide step-by-step instructions for repairing electronic devices"}, {"id": "c", "text": "To promote a specific brand of lightbulbs over its competitors"}, {"id": "d", "text": "To argue that all technology companies are engaged in illegal conspiracies"}]'::jsonb, 0, '{"strategy": "שאלת מטרה/רעיון מרכזי — הפסקה בוחנת את מושג ההתיישנות המתוכננת ואת הוויכוח סביבו.", "correct_reason": "הפסקה סוקרת הגדרה, דוגמה היסטורית, פרשנות מקילה, ותגובה רגולטורית — דיון מאוזן.", "options_analysis": ["נכון! בחינת המושג והוויכוח סביבו = המטרה המרכזית", "לא מוזכר בפסקה כלל", "לא מוזכר בפסקה כלל", "קיצוני מדי — הפסקה מציגה גם פרשנות מקילה, לא רק האשמה"]}', 2.12, 2.0, 0.25, 5, 'ai', NULL, true),
('7599bfdf-c181-4745-bace-7ef93f2a1c1d', 'reading_comprehension', 'According to the passage, what did the Phoebus cartel do?', '1a4334e6-a7c5-4bd5-a858-e7db28f6e2be', '[{"id": "c", "text": "Invented the first incandescent lightbulb in the 1920s"}, {"id": "a", "text": "Colluded to limit lightbulb lifespan to approximately a thousand hours despite having the ability to make them last longer"}, {"id": "d", "text": "Was investigated but found innocent of any wrongdoing"}, {"id": "b", "text": "Extended the lifespan of lightbulbs to improve consumer satisfaction"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את התיאור של קרטל פויבוס בפסקה.", "correct_reason": "הפסקה אומרת: ''colluded to limit the lifespan of incandescent bulbs to roughly a thousand hours, despite possessing the technical capacity to produce bulbs that lasted far longer''.", "options_analysis": ["לא נאמר בפסקה — אין אזכור להמצאת הנורה", "נכון! נאמר במפורש בפסקה", "סותר את כל התיאור בפסקה שמציג זאת כדוגמה מתועדת", "הפוך גמור ממה שנאמר בפסקה"]}', 2.11, 2.0, 0.25, 5, 'ai', NULL, true),
('3c0d67ae-e04d-4109-8f96-c52e88c70cc3', 'reading_comprehension', 'The word "charitable" in the passage most closely means:', '1a4334e6-a7c5-4bd5-a858-e7db28f6e2be', '[{"id": "a", "text": "irrelevant"}, {"id": "b", "text": "legally binding"}, {"id": "d", "text": "generous or favorable"}, {"id": "c", "text": "harsh and critical"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''a more charitable interpretation''.", "correct_reason": "charitable = נדיבה/סלחנית/מקילה.", "options_analysis": ["לא קשור למשמעות המילה", "לא קשור למשמעות המילה", "נכון! charitable = נדיבה/מקילה", "הפוך גמור למשמעות המילה בהקשר זה"]}', 1.78, 2.0, 0.25, 5, 'ai', NULL, true),
('5b38e8ba-f33d-4599-ba03-472aaefabfcd', 'reading_comprehension', 'According to the passage, what argument do proponents of the more charitable interpretation make?', '1a4334e6-a7c5-4bd5-a858-e7db28f6e2be', '[{"id": "d", "text": "That the Phoebus cartel was a complete myth with no historical basis"}, {"id": "b", "text": "That planned obsolescence never actually occurs in any industry"}, {"id": "a", "text": "That all product decline is due to deliberate sabotage by manufacturers"}, {"id": "c", "text": "That diminished utility of older devices can reflect genuine technological progress rather than intentional sabotage"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את טיעון הפרשנות המקילה בפסקה.", "correct_reason": "הפסקה אומרת: ''its diminished utility relative to newer models reflects genuine advances in processing power and software design rather than deliberate sabotage''.", "options_analysis": ["סותר את התיאור המפורט של הקרטל כדוגמה מתועדת היטב", "סותר את הדיון כולו שמניח שהתופעה קיימת במידה מסוימת", "הפוך גמור מהטיעון המקיל שמוצג בפסקה", "נכון! נאמר במפורש בפסקה"]}', 1.88, 2.0, 0.25, 5, 'ai', NULL, true),
('5ffa0a0a-805d-4abe-9d29-f4ecb742252a', 'reading_comprehension', 'According to the passage, why have industry groups resisted "right to repair" legislation?', '1a4334e6-a7c5-4bd5-a858-e7db28f6e2be', '[{"id": "a", "text": "Citing concerns about product safety and intellectual property, though critics suspect a reluctance to lose profits from replacement sales"}, {"id": "c", "text": "Because it has no effect on their profits whatsoever"}, {"id": "b", "text": "Because such legislation has never been proposed anywhere"}, {"id": "d", "text": "Because they believe repair shops are more competent than their own technicians"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את הסיבה להתנגדות התעשייה בפסקה.", "correct_reason": "הפסקה אומרת: ''industry groups have resisted on the grounds that it could compromise product safety and intellectual property protections, though critics counter that such objections often mask a reluctance to forgo the profits''.", "options_analysis": ["נכון! נאמר במפורש בפסקה, כולל הפרשנות הביקורתית", "סותר את קיום ההתנגדות המתוארת בפסקה", "סותר את קיום החקיקה המתוארת בפסקה", "לא נאמר בפסקה כלל"]}', 2.13, 2.0, 0.25, 5, 'ai', NULL, true);